module alu_16bit #(parameter DATA_WIDTH = 16)(input  wire [DATA_WIDTH-1:0] a, input  wire [DATA_WIDTH-1:0] b, input  wire [2:0] opcode, output reg  [DATA_WIDTH-1:0] result, output reg                   carry_out, output wire                  zero); assign zero = (result == {DATA_WIDTH{1'b0}}); wire        is_sub; wire [DATA_WIDTH-1:0] b_operand; wire [DATA_WIDTH:0]   adder_result; assign is_sub    = (opcode == 3'b001); assign b_operand = b ^ {DATA_WIDTH{is_sub}}; assign adder_result = {1'b0, a} + {1'b0, b_operand} + { {DATA_WIDTH{1'b0}}, is_sub }; always @(*) begin result     = {DATA_WIDTH{1'b0}}; carry_out  = 1'b0; case (opcode[2:0]) 3'b000: begin result     = adder_result[DATA_WIDTH-1:0]; carry_out  = adder_result[DATA_WIDTH]; end 3'b001: begin result     = adder_result[DATA_WIDTH-1:0]; carry_out  = ~adder_result[DATA_WIDTH]; end 3'b010: begin result     = a & b; carry_out  = 1'b0; end 3'b011: begin result     = a | b; carry_out  = 1'b0; end 3'b100: begin result     = a ^ b; carry_out  = 1'b0; end 3'b101: begin result     = a << b[3:0]; carry_out  = 1'b0; end 3'b110: begin result     = a >> b[3:0]; carry_out  = 1'b0; end 3'b111: begin result     = a; carry_out  = 1'b0; end default: begin result     = {DATA_WIDTH{1'b0}}; carry_out  = 1'b0; end endcase end endmodule